Method.Source:
    /// <summary>
    /// TO include cancelled and zero quantity lines
    /// </summary>
    /// <param name = "_forupdate">boolean</param>
    /// <returns>query</returns>
    Query querySalesParmLine(boolean _forupdate)
    {
        Query                 query = next querySalesParmLine(_forupdate);
        QueryBuildDataSource  queryParmLineDS;
        METCustParameters     METCustParameters;
        QueryBuildDataSource  querySalesLineDS;

        if (this.Ordering == DocumentStatus::Confirmation) 
        {
            METCustParameters = METCustParameters::Find();
            if(METCustParameters.IncludeLineWithZeroQty || METCustParameters.IncludeCancelledLines)
            {
                queryParmLineDS = query.dataSourceTable(tableNum(SalesParmLine));
                queryParmLineDS.clearRange(fieldNum(SalesParmLine, DeliverNow));
                querySalesLineDS = queryParmLineDS.addDataSource(tableNum(SalesLine));
                querySalesLineDS.relations(true);

                if(METCustParameters.IncludeLineWithZeroQty && !METCustParameters.IncludeCancelledLines)
                {
                    querySalesLineDS.addRange(fieldNum(SalesLine, SalesStatus)).value(SysQuery::valueNot(enum2str(SalesStatus::Canceled)));
                }
            }
        }

        return query;
    }
